WITH cleaned AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, IF(is_flagged, 'Yes', 'No') is_flagged_label FROM transactions WHERE txn_time > TIMESTAMP '2023-05-21 14:00:00' AND account_id IN (3, 14, 18, 39)), with_gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM cleaned), sessions_transactions AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, is_flagged_label, SUM(session_start_flag) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps), with_windows AS (SELECT id, account_id, txn_type, txn_time, merchant, is_flagged, island_id, MIN(amount) OVER (PARTITION BY txn_type, account_id ORDER BY island_id, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) last4_min_amount, COUNT(amount) OVER (PARTITION BY txn_type, account_id ORDER BY island_id, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) last4_count_amount, AVG(amount) OVER (PARTITION BY txn_type, account_id ORDER BY island_id, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) last4_avg_amount FROM sessions_transactions), flagged AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM with_windows), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT account_id, SIZE(COLLECT_SET(txn_type)) AS num_txn_types, SUM(CASE WHEN txn_type = 'FEE' THEN last4_count_amount ELSE 0 END) AS fee_last4_count_amount, COUNT(*) FILTER (WHERE merchant = 'Shell') AS shell_rows, COUNT_IF(merchant = 'Starbucks') AS starbucks_events, SORT_ARRAY(COLLECT_SET(txn_type)) AS txn_type_list, ROUND(AVG(last4_avg_amount), 2) AS avg_last4_avg_amount FROM islands GROUP BY 1 HAVING fee_last4_count_amount > 0;
